head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00007";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00007.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "img_91", fn: function(){ return ((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())); } }, { id: "img_92", fn: function(){ return ((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())); } }, { id: "c_otherwise_93", fn: function(){ return (!(((dma_inspectionResult.get("valid") ?? (() => { throw new Error("unresolved:" + "inspectionResult.valid"); })())))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {

        // openResult();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007.onpageload' }); }
};

// [A] 초기 목록 미해결 — jldfil00007: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_inspectionResultDocumentErrors_3_oncellclick
 * @description grd_inspectionResultDocumentErrors_3 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_inspectionResultDocumentErrors_3_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_inspectionResultDocumentErrors');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_inspectionResultDocumentErrors */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        scwin.focusError(r["formCd"], r["formVer"], r["formDiv"], r["xpath"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_inspectionResultDocumentErrors_3.oncellclick' });
    }
};

/**
 * @method
 * @name img_91_onclick
 * @description img_91 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_91_onclick = function(e){
    try {
        scwin.submit()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007.img_91_onclick' }); }
};

/**
 * @method
 * @name img_92_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_92_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007.img_92_onclick' }); }
};

/**
 * @method
 * @name img_94_onclick
 * @description img_94 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_94_onclick = function(e){
    try {
        scwin.close()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00007.img_94_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name focusError
 * @description focus Error 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} xpath xpath
 * @returns {void}
 * @hidden N
 */
scwin.focusError = function (formCd, formVer, wrtrptMaindocTpCd, xpath) {
    const nsArray = eval("getNamespaces_" + formCd + "()");
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).focusError === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).focusError(formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray) : void 0), $c.win.closePopup([formCd, formVer, wrtrptMaindocTpCd, xpath, nsArray]));
};

/**
 * @method
 * @name submit
 * @description submit 처리
 * @returns {void}
 * @hidden N
 */
scwin.submit = function () {
    const obj = $c.util.getComponent('ipt_prnInfoIncldSubmitYn').getValue();
    (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_submit === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).fn_submit(obj) : void 0), $c.win.closePopup([obj]));
};

/**
 * @method
 * @name close
 * @description close 처리
 * @returns {void}
 * @hidden N
 */
scwin.close = function () {
    $c.win.closePopup();
};

/**
 * @method
 * @name Namespace
 * @description Namespace 처리
 * @param {*} prefix prefix
 * @param {*} uri uri
 * @returns {void}
 * @hidden N
 */
scwin.Namespace = function (prefix, uri) {
    this.prefix = prefix;
    this.uri = uri;
};
